    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Pointer();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Service(ref Context c,IntPtr args,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"VM property module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static string Text(IntPtr p){Check(p!=IntPtr.Zero&&Marshal.ReadInt64(p,-16)==16&&Marshal.ReadInt32(p,-20)==1,"Malformed VM property String");IntPtr chars=Marshal.ReadIntPtr(p);long bytes=Marshal.ReadInt64(chars,-16);Check(bytes>=0&&(bytes&1)==0&&bytes<=131070&&Marshal.ReadInt64(chars,-8)==261,"Malformed VM property chars");return Marshal.PtrToStringUni(chars,checked((int)bytes/2));}
    static void Array(IntPtr a,IntPtr pool,string[] keys,string[] values){int count=keys.Length*2+1;Check(a!=IntPtr.Zero&&Marshal.ReadInt64(a,-16)==count*8L&&Marshal.ReadInt32(a,-20)==count&&Marshal.ReadIntPtr(a,-8)==Marshal.ReadIntPtr(pool,32),"VM property array shape/type mismatch");for(int i=0;i<keys.Length;i++){Check(Text(Marshal.ReadIntPtr(a,i*16))==keys[i],"VM key mismatch "+i);Check(Text(Marshal.ReadIntPtr(a,i*16+8))==values[i],"VM value mismatch "+keys[i]);}Check(Marshal.ReadIntPtr(a,(count-1)*8)==IntPtr.Zero,"Missing terminal null key");}
    static IntPtr Invoke(Entry entry){Context c=new Context();ulong bits=entry(ref c,new ulong[0]);Check(bits!=0&&c.Kind==0&&c.Depth==0,"Raw.vmProperties VM entry failed: "+c.Kind);return new IntPtr(unchecked((long)bits));}
    static int Reachable(IntPtr roots,uint n){var live=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!live.Add(p))continue;uint flags=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((flags&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&live.Count<1048576,"Malformed VM property root graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return live.Count;}
