    public static void Basic(string dll,string[] keys,string[] values){IntPtr m=Open(dll),heap=IntPtr.Zero;try{heap=Fn<Create>(m,"boom_heap_create")(16*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"VM heap binding failed");IntPtr pool=Fn<Pointer>(m,"boom_get_vm_property_pool")();var entry=Fn<Entry>(m,"boom_entry");IntPtr a=Invoke(entry),b=Invoke(entry);Array(a,pool,keys,values);Array(b,pool,keys,values);Check(a!=b,"Native VM properties returned a shared mutable array");for(int i=0;i<keys.Length*2;i++)Check(Marshal.ReadIntPtr(a,i*8)==Marshal.ReadIntPtr(b,i*8),"Warm VM properties did not reuse immutable literals");Marshal.WriteIntPtr(a,IntPtr.Zero);Array(b,pool,keys,values);GC(m,heap,b);Array(b,pool,keys,values);GC(m,heap);long baseline=Marshal.ReadInt64(heap,56);for(int i=0;i<128;i++){IntPtr v=Invoke(entry);Check(Marshal.ReadInt64(heap,56)==baseline+1,"Warm VM property call allocated beyond its fresh array");Array(v,pool,keys,values);GC(m,heap);Check(Marshal.ReadInt64(heap,56)==baseline,"Temporary VM property array retained");}
        var service=Fn<Service>(m,"boom_vm_properties");Context c=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(service(ref c,IntPtr.Zero,pool)==IntPtr.Zero&&c.Kind==9&&c.PC==17&&c.Method==23&&c.Depth==3&&Marshal.ReadInt64(heap,56)==baseline,"Pending VM exception was changed");
        IntPtr copy=Marshal.AllocHGlobal(64),badRows=Marshal.AllocHGlobal(keys.Length*8);try{byte[] bytes=new byte[64];Marshal.Copy(pool,bytes,0,64);foreach(int offset in new[]{0,4,8,12,16,24,32,40,56}){Marshal.Copy(bytes,0,copy,64);if(offset>=16)Marshal.WriteIntPtr(copy,offset,IntPtr.Zero);else Marshal.WriteInt32(copy,offset,offset==8?0:7);if(offset==56)Marshal.WriteInt64(copy,offset,1);c=new Context{PC=17,Method=23};Check(service(ref c,IntPtr.Zero,copy)==IntPtr.Zero&&c.Kind==7&&c.PC==17&&c.Method==23&&Marshal.ReadInt64(heap,56)==baseline,"Malformed VM pool accepted: "+offset);}
            Marshal.Copy(bytes,0,copy,64);Marshal.WriteInt32(copy,8,2049);c=new Context();Check(service(ref c,IntPtr.Zero,copy)==IntPtr.Zero&&c.Kind==7,"Oversized VM property table accepted");
            byte[] rows=new byte[keys.Length*8];Marshal.Copy(Marshal.ReadIntPtr(pool,40),rows,0,rows.Length);Marshal.Copy(rows,0,badRows,rows.Length);Marshal.WriteInt32(badRows,Marshal.ReadInt32(Marshal.ReadIntPtr(pool,24),16));Marshal.Copy(bytes,0,copy,64);Marshal.WriteIntPtr(copy,40,badRows);c=new Context();Check(service(ref c,IntPtr.Zero,copy)==IntPtr.Zero&&c.Kind==7&&Marshal.ReadInt64(heap,56)==baseline,"Invalid literal ID allocated or escaped");
            IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);Check(foreign!=IntPtr.Zero,"Foreign test heap failed");try{Marshal.Copy(bytes,0,copy,64);Marshal.WriteIntPtr(copy,48,foreign);c=new Context();Check(service(ref c,IntPtr.Zero,copy)==IntPtr.Zero&&c.Kind==7&&Marshal.ReadInt64(heap,56)==baseline,"Foreign VM heap accepted");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign test heap cleanup failed");}
        }finally{Marshal.FreeHGlobal(badRows);Marshal.FreeHGlobal(copy);}
    }finally{if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"VM heap cleanup failed");FreeLibrary(m);}}
    public static void Parallel(string dll,string runtime,string[] keys,string[] values){IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero,p=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;const uint n=2049;try{heap=Fn<Create>(m,"boom_heap_create")(32*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Worker VM heap binding failed");IntPtr pool=Fn<Pointer>(m,"boom_get_vm_property_pool")();p=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(p!=IntPtr.Zero,"VM worker pool failed");input=Marshal.AllocHGlobal((int)n*128);output=Marshal.AllocHGlobal((int)n*32);for(int batch=0;batch<3;batch++){Check(Fn<PoolRun>(r,"boom_pool_run")(p,GetProcAddress(m,"boom_entry"),input,output,n)==0,"VM property worker batch failed");var arrays=new HashSet<IntPtr>();for(int i=0;i<n;i++){IntPtr a=Marshal.ReadIntPtr(output,i*32);Check(arrays.Add(a)&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"VM results or contexts crossed worker records");Array(a,pool,keys,values);}GC(m,heap);}}
        finally{if(p!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(p)==0,"VM workers active at cleanup");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Worker heap cleanup failed");FreeLibrary(r);FreeLibrary(m);}}
    public static void Oom(string dll,string runtime,string[] keys,string[] values){IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero;try{heap=Fn<Create>(m,"boom_heap_create")(65536);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"OOM VM heap failed");var alloc=Fn<Alloc>(r,"boom_heap_alloc");var entry=Fn<Entry>(m,"boom_entry");IntPtr pool=Fn<Pointer>(m,"boom_get_vm_property_pool")();ulong bytes=checked((ulong)(keys.Length*2+1)*8);IntPtr hole=alloc(heap,bytes,0,267);Check(hole!=IntPtr.Zero,"VM OOM hole setup failed");var fillers=new List<IntPtr>();IntPtr v;while((v=alloc(heap,4096,0,267))!=IntPtr.Zero){fillers.Add(v);Check(fillers.Count<4096,"VM OOM filler overflow");}while((v=alloc(heap,0,0,267))!=IntPtr.Zero){fillers.Add(v);Check(fillers.Count<4096,"VM OOM filler overflow");}var c=new Context{PC=17,Method=23};Check(entry(ref c,new ulong[0])==0&&c.Kind==3&&c.Depth==0,"Cold full-heap VM call did not report OOM");GC(m,heap,fillers.ToArray());long before=Marshal.ReadInt64(heap,56);c=new Context{PC=17,Method=23};Check(entry(ref c,new ulong[0])==0&&c.Kind==3&&Marshal.ReadInt64(heap,56)==before+1,"Partial VM array allocation was not exercised");GC(m,heap,fillers.ToArray());Check(Marshal.ReadInt64(heap,56)==before,"Partial VM array survived quiescent collection");GC(m,heap);Array(Invoke(entry),pool,keys,values);GC(m,heap);before=Marshal.ReadInt64(heap,56);while(alloc(heap,4096,0,267)!=IntPtr.Zero){}while(alloc(heap,0,0,267)!=IntPtr.Zero){}c=new Context();Check(entry(ref c,new ulong[0])==0&&c.Kind==3,"Warm full-heap VM call did not report OOM");GC(m,heap);Check(Marshal.ReadInt64(heap,56)==before,"Rooted VM literals lost after OOM");Array(Invoke(entry),pool,keys,values);GC(m,heap);
    }finally{if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"VM OOM heap cleanup failed");FreeLibrary(r);FreeLibrary(m);}}
}
